import { createDiscover } from './discover.js?v=1583';
import { phrasebook, routeGuides, railMaps, immigrationQA, etiquette } from './travel-data.js?v=1583';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>crypto.randomUUID(), today=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return p.year+'-'+p.month+'-'+p.day};
const icons={home:'M3 10 12 3l9 7M5 9v12h5v-6h4v6h5V9',plan:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16M8 14h2M14 14h2',travel:'M5 4h14v13H5zM5 11h14M8 20l-2 2M16 20l2 2M8 15h1M15 15h1',money:'M3 6h17v15H3zM3 6l14-3v3M15 11h6v5h-6z',trip:'M4 7h16v14H4zM8 7V3h8v4M9 7v14M15 7v14',plus:'M12 5v14M5 12h14',help:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M9 8a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01',download:'M12 3v12M7 10l5 5 5-5M4 15v6h16v-6',check:'M5 12l4 4L19 6',shop:'M4 7h16l-1 14H5zM8 8V5a4 4 0 0 1 8 0v3',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',plane:'m3 12 7-2V4c0-3 4-3 4 0v6l7 2v3l-7-1v5l3 2H7l3-2v-5l-7 1z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0M15 10a3 3 0 1 0-6 0 3 3 0 0 0 6 0',edit:'m4 16 12-12 4 4L8 20H4z',refresh:'M20 7a9 9 0 1 0 1 9M20 2v5h-5',chat:'M3 3h18v14H9l-6 4zM7 8h10M7 12h7',file:'M5 2h9l5 5v15H5zM14 2v6h5M8 12h8M8 16h6',trash:'M3 6h18M6 6l1 15h10l1-15M9 6V3h6v3'};
const icon=n=>`<svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.file}"/></svg>`;
const btn=(text,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const link=(text,url)=>`<a class="btn" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${text}</a>`;
const jpy=n=>'¥'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2});const thb=n=>'฿'+Number(n).toLocaleString('en-US',{maximumFractionDigits:2});
function initialTrip(){return {id:uid(),name:'ทริปของฉัน',setupComplete:false,city:'tokyo',start:today(),end:today(),people:['ฉัน'],budget:0,daily:0,cash:0,airport:'nrt',meeting:'',contact:'',backup:'',rate:.23,rateSource:'เรทตัวอย่าง • กรุณาตั้งเรทจริง',rateDate:'',checks:{},step:{nrt:0,hnd:0,kix:0},events:[],hotels:[],expenses:[],moves:[],trash:[],docs:[],favorites:[],immigrationProfile:{},lastBackup:''};}
let S;try{S=JSON.parse(localStorage.getItem('tabi-v1'));if(!S||S.version!==1||!Array.isArray(S.trips))throw 0;}catch{const t=initialTrip();S={version:1,current:t.id,trips:[t]};}
let page=location.hash.slice(1)||'home', day='',guideAirport='',moneyTab='ledger',savedTimer;const T=()=>S.trips.find(t=>t.id===S.current)||S.trips[0];
function save(){try{localStorage.setItem('tabi-v1',JSON.stringify(S));return true}catch{toast('บันทึกไม่ได้ พื้นที่อาจเต็ม กรุณาส่งออกข้อมูลสำรอง');return false}}
function toast(m){const error=$('#modal[open] .formerror');if(error){error.textContent=m;error.hidden=false}$('#toast').textContent=m;$('#toast').style.display='block';clearTimeout(savedTimer);savedTimer=setTimeout(()=>$('#toast').style.display='none',4300)}
const dual=(n,r=T().rate)=>`${jpy(n)} <span class="muted">≈ ${thb(n*r)}</span>`;
const formatDate=d=>d?new Intl.DateTimeFormat('th-TH',{day:'numeric',month:'short'}).format(new Date(d+'T12:00:00')):'ยังไม่ระบุ';
const field=(label,name,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
const textarea=(label,name,value='')=>`<label class="field">${label}<textarea name="${name}">${esc(value)}</textarea></label>`;
const modal=(title,body)=>{$('#modalbody').innerHTML=`<button class="close" aria-label="ปิด" data-action="close">×</button><h2>${title}</h2>${body}`;$('#modal').showModal()};
const formModal=(title,id,body)=>modal(title,`<form id="${id}" ${id==='expenseform'?'novalidate':''}><p class="formerror" role="alert" hidden></p>${body}<div class="dialogactions">${btn('ยกเลิก','close')}<button class="btn primary" type="submit">บันทึก</button></div></form>`);
const nav=[['now','ตอนนี้','refresh'],['home','วันนี้','home'],['plan','แผนเที่ยว','plan'],['travel','เดินทาง','travel'],['money','บัญชี','money'],['trip','ทริปของฉัน','trip']];
function totals(t=T()){let cost=0,paid=0,debt=0,debtTHB=0,cash=t.cash||0,dayCost=0,income=0,tripCost=0;for(const e of t.expenses){cost+=e.mine*e.rate;tripCost+=e.amount*e.rate;if(e.payer==='me')paid+=e.amount*e.rate;const d=(e.payer==='me'?e.amount:0)-e.mine;if(e.currency==='THB')debtTHB+=d*e.rate;else debt+=d;if(e.payer==='me'&&e.method==='cash'&&e.currency!=='THB')cash-=e.amount;if(e.date===today())dayCost+=e.mine*e.rate}for(const m of t.moves){if(m.kind==='income'){income+=m.amount*(m.rate||t.rate);if(m.method==='cash'&&m.currency!=='THB')cash+=m.amount}if(m.kind==='cash')cash+=m.amount;if(m.kind==='settle'){if(m.currency==='THB')debtTHB-=m.amount*m.rate;else debt-=m.amount;if(m.method==='cash'&&m.currency!=='THB')cash+=m.amount}}return {cost,tripCost,paid,debt,debtTHB,cash,dayCost,income,net:income-cost,remaining:t.budget-cost}}
function title(kicker,title,sub='',actions=''){return `<div class="titleline"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions}</div>`}
function render(){const t=T();if(!nav.some(n=>n[0]===page))page='home';$('#sidebar').innerHTML=`<div class="brand ichi-brand"><span>ICHI</span><small>JAPAN</small></div><div class="side-label">YOUR JOURNEY</div>${nav.map(([id,label,ic])=>`<button class="navbtn ${page===id?'active':''}" data-page="${id}">${icon(ic)}${label}</button>`).join('')}<div class="sidebar-bottom">โตเกียว & โอซาก้า<br>By ichitan<hr style="border:0;border-top:1px solid var(--line);margin:20px 0">${icon('download')} ข้อมูลอยู่ในเครื่องนี้</div>`;$('#bottom').innerHTML=nav.map(([id,label,ic])=>`<button class="navbtn ${page===id?'active':''}" data-page="${id}">${icon(ic)}${label.replace('ของฉัน','').replace('เที่ยว','')}</button>`).join('');$('#topbar').innerHTML=`<span class="tagline ichi-mobile">ICHI <small>JAPAN</small></span><div class="crumb mobilehide">ทริปของฉัน <span style="margin:0 12px">/</span> <b>${esc(t.name)}</b></div><div class="flex"><span class="pill green" id="offlinebadge">${navigator.onLine?'ออนไลน์':'ออฟไลน์'}</span><span class="muted mobilehide" style="font-size:13px">${formatDate(t.start)} – ${formatDate(t.end)}</span><button class="avatar" data-page="trip" aria-label="ตั้งค่าทริป">${esc(t.people[0].slice(0,2))}</button></div>`;$('#app').innerHTML=({home:homeView,plan:planView,travel:travelView,money:moneyView,trip:tripView,now:nowView,discover:()=>discover.view()}[page])();$('#net').textContent=navigator.onLine?'เชื่อมต่ออินเทอร์เน็ต':'ไม่มีอินเทอร์เน็ต • บันทึกในเครื่องได้';if(page==='money'&&moneyTab==='entry')wireWalletForm();if(page==='trip'){renderDocs();offlineRequest(false)}if(page==='money'&&moneyTab==='shop')calcShop();if(page==='money'&&moneyTab==='convert')calcConvert();}
function go(p){page=p;location.hash=p;render();scrollTo(0,0)}
const checklist=[['flight','ตรวจเที่ยวบินและอาคารผู้โดยสาร'],['passport','พาสปอร์ตและเอกสารเข้าเมือง'],['hotel','ที่พักครบทุกคืน'],['meeting','จุดนัดพบและผู้ติดต่อ'],['net','ซิม / eSIM และวิธีเปิดใช้งาน'],['insurance','ประกันและข้อมูลช่วยเหลือ'],['bags','กระเป๋าและน้ำหนักสัมภาระ'],['offline','ทดลองเปิดในโหมดเครื่องบิน']];
function readiness(){const t=T(),n=checklist.filter(([id])=>t.checks[id]).length;return `<div class="card"><div class="cardhead"><h2>พร้อมเดินทางแค่ไหน</h2><span class="muted">${n}/${checklist.length}</span></div><div class="bar"><i style="width:${n/checklist.length*100}%"></i></div><div class="checks">${checklist.slice(0,page==='home'?4:99).map(([id,label])=>`<label class="checkrow"><input type="checkbox" data-check="${id}" ${t.checks[id]?'checked':''}>${label}</label>`).join('')}</div>${page==='home'?`<button class="linkbtn" data-page="trip">ดูเช็กลิสต์ทั้งหมด</button>`:''}</div>`}
function budgetCard(){const t=T(),z=totals();return `<div class="card moneyhero"><div class="cardhead"><span>งบส่วนตัวคงเหลือ</span>${icon('money')}</div><div class="big">${t.budget?thb(z.remaining):'ยังไม่ได้ตั้งงบ'}</div><p class="muted" style="font-size:13px;margin:8px 0 0">${t.budget?`จากงบ ${thb(t.budget)} · คิดเฉพาะส่วนของคุณ`:'เริ่มจดรายจ่ายได้เลย ตั้งงบทีหลังก็ได้'}</p><div class="statline"><div><small>วันนี้ใช้ไป</small><strong>${thb(z.dayCost)}</strong></div><div><small>${z.debt>=0?'รอรับคืน':'ต้องคืนเพื่อน'}</small><strong>${jpy(Math.abs(z.debt))}</strong></div></div></div>`}
function eventRows(events){return events.length?events.map(e=>`<div class="event ${e.done?'done':''}"><time>${esc(e.time||'—')}</time><span class="dot"></span><div><h3>${esc(e.title)}</h3><p>${esc(e.note)}</p>${e.discoverId?`<button type="button" class="btn small" data-discover="detail" data-id="${esc(e.discoverId)}">📍 ดูสถานที่ / แผนที่</button>`:""}</div><button class="btn small" data-action="eventedit" data-id="${e.id}" aria-label="แก้ไข ${esc(e.title)}">${icon('edit')}</button></div>`).join(''):`<div class="empty">วันนี้ยังไม่มีแผน<br>เพิ่มสถานที่หรือเวลานัดหมายได้เลย</div>`}
function homeView(){if(T().setupComplete===false)return title('WELCOME TO ICHI-JAPAN','ญี่ปุ่นทริปนี้ เริ่มในแบบของคุณ','สร้างแผน เก็บค่าใช้จ่าย และเตรียมประโยคไว้ใช้ระหว่างเดินทาง')+`<section class="hero smart-hero"><span class="pill">โตเกียว · โอซาก้า</span><h2>พร้อมเมื่อคุณพร้อม</h2><p>ยังไม่มีแผน ที่พัก หรือรายจ่าย เริ่มจากตั้งชื่อทริป เลือกเมืองและวันเดินทางของคุณ</p>${btn('เริ่มตั้งค่าทริป','tripsettings','primary')}</section><section class="card gap"><h2>ลองใช้คู่มือได้เลย</h2><p>ประโยคพร้อมเสียง แผนที่รถไฟ และคู่มือสนามบิน ยังใช้ได้โดยไม่ต้องสร้างบัญชี</p><div class="flex">${btn('ประโยคและเสียง','phrases')}${btn('แผนที่รถไฟ','showmaps-home')}${btn('เตรียมออฟไลน์','offlinedetails')}</div><p class="note">ข้อมูลของแต่ละคนเก็บในเบราว์เซอร์ที่ใช้งาน ไม่ซิงก์ข้ามเครื่อง อัตราแลกเปลี่ยนเริ่มต้นเป็นเพียงตัวอย่าง กรุณาตั้งเรทก่อนใช้งานบัญชี</p></section>`;const t=T(),now=today(),before=now<t.start,after=now>t.end,focus=before?t.start:after?t.end:now,hotelDate=before?(t.events.find(e=>/ถึงสนามบิน|arrival/i.test(e.title))?.date||t.start):focus,z=totals(),days=Math.max(1,Math.ceil((new Date(t.end)-new Date(now))/864e5)+1),clock=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Tokyo',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date()),ev=t.events.filter(e=>!e.done&&e.date>=focus&&(before||after||e.date>now||!e.time||e.time>=clock)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),next=ev[0],hotel=after?t.hotels.slice().sort((a,b)=>b.from.localeCompare(a.from))[0]:t.hotels.find(h=>h.from<=hotelDate&&h.to>hotelDate),pins=(t.favorites||[]).filter(i=>phrases[i]).slice(0,4),countdown=Math.ceil((new Date(t.start)-new Date(now))/864e5);return title('YOUR JOURNEY, AT A GLANCE',before?`อีก ${countdown} วัน ออกเดินทาง`:after?'เก็บความทรงจำ สรุปทริป':'วันนี้ในญี่ปุ่น',esc(t.name),btn(icon('plus')+' จดรายจ่าย','expense','primary'))+`<div class="dashboard-grid"><div><section class="hero smart-hero"><span class="pill">${before?'ก่อนเดินทาง':after?'จบทริปแล้ว':formatDate(now)}</span><h2>${before?'เตรียมพร้อมทีละเรื่อง':after?'ทริปนี้ใช้ไปเท่าไร?':next?esc(next.title):'วันนี้อยากไปที่ไหน?'}</h2><p>${before?'เช็กที่พัก เอกสาร และเปิดออฟไลน์ให้ได้ก่อนบิน':after?`รวมทั้งทริป ${thb(z.tripCost)} · ส่วนของฉัน ${thb(z.cost)}`:next?`${formatDate(next.date)} ${esc(next.time||'ยังไม่ระบุเวลา')} · ${esc(next.note)}`:'เพิ่มแผน หรือเปิดเส้นทางรถไฟได้เลย'}</p>${btn(before?'ตรวจความพร้อมออฟไลน์':after?'ดูสรุปและส่งออก':'เปิดแผนเที่ยว',before?'offlinedetails':after?'summary':'todayplan','primary')}</section><div class="quick gap"><button data-action="lost">${icon('pin')}ฉันหลงทาง</button><button data-action="favorites">${icon('chat')}ประโยคปักหมุด</button><button data-action="showmaps-home">${icon('travel')}แผนที่รถไฟ</button></div><section class="card gap"><div class="cardhead"><h2>${before?'แผนแรกของทริป':'แผนถัดไป'}</h2><button class="linkbtn" data-page="plan">ดูทั้งหมด</button></div>${next?eventRows(ev.slice(0,3)):'<p class="note">ไม่มีแผนที่ยังรอทำ เพิ่มแผนได้จากหน้าแผนเที่ยว</p>'}<p class="note">อ้างอิงวันที่และแผนที่คุณบันทึก ไม่ใช่สถานะเที่ยวบินหรือรถไฟสด</p></section><section class="card gap"><div class="cardhead"><h2>${before?'ที่พักคืนแรกในญี่ปุ่น':after?'ที่พักในทริป':'ที่พักคืนนี้'}</h2><button class="linkbtn" data-page="trip">จัดการที่พัก</button></div>${hotel?`<h3>${esc(hotel.name)}</h3><p>${esc(hotel.address)}</p>${btn('เปิดที่อยู่ให้เจ้าหน้าที่อ่าน','hotelcard','soft',`data-id="${hotel.id}"`)}`:`<p class="note">ยังไม่มีที่พักครอบคลุม ${formatDate(hotelDate)} ตรวจวันเริ่มทริปกับวันถึงญี่ปุ่น และเพิ่มที่พักให้ครบทุกคืน</p>${btn('เพิ่มที่พัก','hotel','soft')}`}</section><section class="card gap"><div class="cardhead"><h2>หยิบมาพูดได้ทันที</h2>${btn('ดูปักหมุดทั้งหมด','favorites','small')}</div>${pins.length?pins.map(i=>`<button class="pinned-row" data-action="phrase" data-index="${i}"><b>${phrases[i][1]}</b><span lang="ja">${phrases[i][2]}</span></button>`).join(''):'<p class="note">กด ☆ ในหน้าภาษา แล้วประโยคที่ใช้บ่อยจะอยู่ตรงนี้</p>'}</section></div><div><section class="card"><span class="eyebrow">TRIP SPENDING</span><h2 style="margin-top:10px">รวมทั้งทริป ${thb(z.tripCost)}</h2><p>ส่วนของฉัน <b>${thb(z.cost)}</b></p><div class="row"><span>วันนี้ใช้ไป</span><strong>${thb(z.dayCost)}</strong></div><div class="row"><span>เงินสดเยนคงเหลือ</span><strong>${jpy(z.cash)}</strong></div>${!before&&!after&&t.budget?`<p class="notice">งบที่เหลือเฉลี่ยวันละ ${thb(Math.max(0,z.remaining)/days)} สำหรับ ${days} วันที่เหลือ</p>`:''}${btn('ดูรวมก่อนบิน–หลังทริป','summary','full soft')}</section><section class="card gap"><h2>ก่อนออกจากที่พัก</h2><p class="note">${before?'ยืนยันจุดนัดพบและที่พักคืนแรก':after?'ส่งออกบัญชีเก็บไว้ และตรวจเงินที่ต้องคืนกัน':'ตรวจแผนถัดไป เส้นทางกลับที่พัก และเงินสดในมือ'}</p>${btn('ตรวจชุดออฟไลน์','offlinedetails','full')}<p class="note">${backupStatus()}</p>${btn('สำรองทุกทริป','export','full soft')}</section><div class="gap">${readiness()}</div><div class="prep-shortcuts"><button data-action="immigration">${icon('file')}เตรียม ตม.</button><button data-action="manners">${icon('check')}มารยาท</button></div></div></div>`}

function dates(t){let a=[],d=new Date(t.start+'T12:00:00');for(let i=0;i<90&&d.toISOString().slice(0,10)<=t.end;i++){a.push(d.toISOString().slice(0,10));d.setDate(d.getDate()+1)}return a}
function planView(){const t=T(),ds=dates(t);if(!ds.includes(day))day=ds[0];return title('ITINERARY','แผนเที่ยวของเรา','จัดวันให้พอดี แล้วเหลือเวลาให้ความทรงจำ',btn(icon('plus')+' เพิ่มแผน','eventedit','primary'))+`<div class="tabs">${ds.map(d=>`<button class="tab datebtn ${d===day?'active':''}" data-day="${d}">${new Intl.DateTimeFormat('th',{weekday:'short'}).format(new Date(d+'T12:00:00'))}<b>${Number(d.slice(-2))}</b></button>`).join('')}</div><div class="grid cols"><div class="card"><div class="cardhead"><h2>${formatDate(day)}</h2><span class="pill">เวลาท้องถิ่นตามรายการ</span></div>${eventRows(t.events.filter(e=>e.date===day).sort((a,b)=>a.time.localeCompare(b.time)))}</div><div><div class="card"><h2>สิ่งที่ยังรอยืนยัน</h2><p class="note">${t.meeting?'จุดนัดพบ: '+esc(t.meeting):'จุดนัดพบหลังออกจากสนามบินยังไม่ระบุ'}</p>${btn('เพิ่มหรือแก้ไขข้อมูลทริป','tripsettings','full')}</div><div class="card gap"><h2>เผื่อแผนเปลี่ยน</h2><p>${esc(t.backup||'บันทึกวิธีติดต่อ จุดนัดสำรอง หรือสิ่งที่จะทำหากพลาดรถไว้ที่นี่')}</p>${btn('แก้ไขแผนสำรอง','tripsettings')}</div></div></div>`}
