let travelTab='guide';
function legacyMoneyView(){const t=T(),z=totals();return title('YOUR TRAVEL WALLET','ใช้เงินอย่างสบายใจ','ราคาเยนคู่บาท · บันทึกตามเรทของแต่ละรายการ',btn(icon('plus')+' เพิ่มรายการ','expense','primary'))+`<div class="tabs">${[['ledger','บัญชีทริป'],['convert','แปลงเงิน'],['shop','ส่วนลด & Tax-free']].map(([v,l])=>`<button class="tab ${moneyTab===v?'active':''}" data-money="${v}">${l}</button>`).join('')}</div>`+(moneyTab==='ledger'?`<div class="grid three"><div class="card moneyhero"><div class="muted">งบส่วนตัวคงเหลือ</div><div class="big" style="margin-top:10px">${t.budget?thb(z.remaining):'ยังไม่ตั้งงบ'}</div><p class="note" style="color:#d2dfd8">ใช้ไป ${thb(z.cost)} ${t.budget?'จาก '+thb(t.budget):''}</p></div><div class="card"><div class="muted">เงินสดของฉันคงเหลือ</div><div class="big" style="margin-top:10px">${jpy(z.cash)}</div><p class="note">≈ ${thb(z.cash*t.rate)} · แยกจากงบส่วนตัว</p></div><div class="card"><div class="muted">${z.debt>=0?'เพื่อนต้องคืนฉัน':'ฉันต้องคืนเพื่อน'}</div><div class="big" style="margin-top:10px">${jpy(Math.abs(z.debt))}</div><p class="note">≈ ${thb(Math.abs(z.debt)*t.rate)}</p></div></div><div class="flex gap">${btn('ตั้งงบ / เงินสดเริ่มต้น','tripsettings')}${btn('เพิ่มเงินสด / ถอนเงิน','cash')}${btn('บันทึกการคืนเงิน','settle')}${btn('รับคืนจากร้าน','refund')}${btn(icon('trash')+' รายการที่ลบ','trash')}</div>${t.daily&&z.dayCost>t.daily?'<div class="notice warn">วันนี้ใช้เกินงบรายวันที่ตั้งไว้</div>':''}${t.budget&&z.remaining<0?'<div class="notice warn">ยอดใช้ส่วนตัวเกินงบทั้งทริปแล้ว</div>':''}<div class="grid cols gap"><section class="card"><div class="cardhead"><h2>รายการค่าใช้จ่าย</h2><span class="muted">${t.expenses.length} รายการ</span></div>${t.expenses.length?t.expenses.slice().reverse().map(e=>`<div class="listitem"><span class="expenseicon">${icon(e.category==='ซื้อของ'?'shop':'money')}</span><div class="grow"><h3>${esc(e.title)}</h3><p>${formatDate(e.date)} · ${esc(e.category)} · ${esc(e.payer==='me'?t.people[0]:t.people[1])} จ่าย</p><p>ส่วนของฉัน ${jpy(e.mine)} · ${e.method==='cash'?'เงินสด':'บัตร/บัตรเดินทาง'}</p></div><div class="rightalign"><strong>${jpy(e.amount)}</strong><p>≈ ${thb(e.amount*e.rate)}</p><button class="linkbtn" data-action="expense" data-id="${e.id}">แก้ไข</button></div></div>`).join(''):'<div class="empty">ยังไม่มีรายจ่ายจริง<br>กด “เพิ่มรายการ” เพื่อเริ่มบันทึก</div>'}</section><section class="card"><h2>ส่วนของฉันแยกตามหมวด</h2>${['อาหาร','เดินทาง','ที่พัก','ตั๋วเที่ยว','ซื้อของ','อื่น ๆ'].map(c=>`<div class="row"><span>${c}</span><strong>${thb(t.expenses.filter(e=>e.category===c).reduce((a,e)=>a+e.mine*e.rate,0))}</strong></div>`).join('')}<details><summary>เงินเข้าออกที่ไม่ใช่ค่าใช้จ่าย (${t.moves.length})</summary>${t.moves.map(m=>`<div class="row"><span>${m.kind==='settle'?'คืนเงินระหว่างกัน':'เพิ่ม/ลดเงินสด'}<p>${formatDate(m.date)}</p></span><span>${jpy(m.amount)} ${btn('ลบ','movedelete','small',`data-id="${m.id}"`)}</span></div>`).join('')}</details></section></div>`:moneyTab==='convert'?`<div class="grid two"><section class="card"><h2>เยน ↔ บาท</h2><div class="gap">${select('สกุลเงินที่กรอก','convertCurrency',[['JPY','เยน (JPY)'],['THB','บาท (THB)']],'JPY')}${field('จำนวนเงิน','convertAmount',1000,'number','min="0" step="any"')}</div><div id="convertResult" class="valuecard"></div></section><section class="card"><h2>เรทที่ใช้ในทริป</h2><p class="big">${Number(t.rate).toFixed(5)}</p><p class="note">บาทต่อ 1 เยน · ${esc(t.rateSource)} ${esc(t.rateDate)}</p><div class="flex">${btn('อัปเดตเรทล่าสุด','ratefetch','primary')}${btn('ตั้งเรทแลกเงินจริง','rateset')}</div><p class="note">ข้อมูลออนไลน์จาก Frankfurter เป็นเรทอ้างอิงรายวัน ไม่ใช่เรทร้านแลกเงินหรือบัตร รายการเดิมจะไม่เปลี่ยนเมื่ออัปเดตเรท</p></section></div>`:shopView())}
function shopView(){return `<div class="grid two"><section class="card"><h2>ลองคิดก่อนซื้อ</h2><form id="shopform" class="gap">${field('ราคาป้ายรวมทุกชิ้น (เยน)','price',10000,'number','min="0" step="any"')}${select('ราคาป้าย','included',[['yes','รวมภาษีแล้ว'],['no','ยังไม่รวมภาษี']],'yes')}<div class="grid two formgrid">${field('ส่วนลด (%)','discount',0,'number','min="0" max="100" step="any"')}${field('คูปองลดเพิ่ม (เยน)','coupon',0,'number','min="0" step="any"')}</div>${select('อัตราภาษีของสินค้า','tax',[['10','10%'],['8','8%']],'10')}${field('วันที่ซื้อ','purchase',T().start,'date','required')}<label class="checkboxlabel"><input name="eligible" type="checkbox">ร้านยืนยันว่าผู้ซื้อและสินค้านี้เข้าเงื่อนไข Tax-free และจะนำออกนอกญี่ปุ่น</label>${field('ค่าธรรมเนียมที่หักจากเงินคืน (เยน)','fee',0,'number','min="0" step="any"')}<p class="note">คิดส่วนลดเปอร์เซ็นต์ก่อน แล้วหักคูปองจากราคาตามชนิดป้ายที่เลือก ใช้อัตราภาษีเดียวต่อครั้ง หากมีหลายอัตราให้แยกคำนวณ</p></form></section><div><section class="card"><h2>ราคาที่ต้องเตรียมจ่าย</h2><div id="shopResult" class="gap"></div>${btn('ซื้อแล้ว · บันทึกค่าใช้จ่าย','shopbuy','primary full')}</section><section class="card gap"><h2>Tax-free สำหรับทริปนี้</h2><p class="note">ซื้อวันที่ 1 พ.ย. 2026 เป็นต้นไป: จ่ายราคารวมภาษีก่อน แล้วรับคืนหลังผ่านขั้นตอนยืนยันนำสินค้าออก เกณฑ์ยอดซื้ออย่างน้อย ¥5,000 ก่อนภาษีต่อร้านต่อวัน</p><details><summary>ต้องทำอะไรเพื่อรับเงินคืน?</summary><ol style="padding-left:20px"><li>แสดงพาสปอร์ตและให้ร้านตรวจสิทธิ์ เก็บใบเสร็จและวิธีรับเงินคืน</li><li>นำสินค้าออกภายใน 90 วันจากวันซื้อ และให้พร้อมตรวจ</li><li>ทำขั้นตอนศุลกากรก่อนฝากกระเป๋ากับสายการบินตามแนวทางสนามบิน</li><li>ร้านหรือผู้ให้บริการเป็นผู้คืนเงิน ตรวจค่าธรรมเนียมและเวลาได้รับกับร้าน</li><li>บันทึกรับคืนในบัญชีเมื่อได้รับจริง</li></ol><p>ก่อน 1 พ.ย. 2026 ใช้ระบบเดิมและเงื่อนไขสินค้าเพิ่มเติม เครื่องนี้แสดงเพียงประมาณการ ไม่ยืนยันสิทธิ์</p></details><p class="note">ตรวจ 29 ก.ย. 2026 · <a target="_blank" rel="noopener" href="https://www.mlit.go.jp/kankocho/tax-free/page01_000001_00028.html">Japan Tourism Agency</a></p></section></div></div>`}
let shopResult=null;
function calculateShop(v,rate){let price=Number(v.price),disc=Number(v.discount),coupon=Number(v.coupon),tax=Number(v.tax)/100,fee=Number(v.fee);if(![price,disc,coupon,tax,fee].every(Number.isFinite)||price<0||disc<0||disc>100||coupon<0||fee<0)throw Error('กรุณาตรวจตัวเลข');const discounted=Math.max(0,price*(1-disc/100)-coupon),base=v.included==='yes'?discounted/(1+tax):discounted,gross=v.included==='yes'?discounted:discounted*(1+tax),taxAmount=gross-base,eligible=!!v.eligible&&base>=5000,refund=eligible?Math.max(0,taxAmount-fee):0,modern=v.purchase>='2026-11-01',pay=modern?gross:gross-refund;return {base,gross,refund,pay,net:gross-refund,modern,eligible,rate}}
function calcShop(){const form=$('#shopform');if(!form)return;try{const v=Object.fromEntries(new FormData(form));shopResult=calculateShop(v,T().rate);const r=shopResult;$('#shopResult').innerHTML=`<div class="valuecard"><span>จ่ายจริง${r.modern?'ที่ร้าน':''}</span><div class="big">${jpy(r.pay)}</div><div class="muted">≈ ${thb(r.pay*r.rate)}</div></div><div class="row"><span>${r.modern?'คาดว่าจะได้รับคืน':'ภาษีที่ประหยัดสุทธิ'}</span><strong>${jpy(r.refund)}</strong></div><div class="row"><span>สุทธิเมื่อได้สิทธิ์ / รับคืน</span><strong>${jpy(r.net)}<p>≈ ${thb(r.net*r.rate)}</p></strong></div><p class="note">ราคาก่อนภาษีหลังส่วนลด ${jpy(r.base)} · ใช้เรท ${r.rate}</p>${r.base<5000?'<div class="notice warn">ยอดครั้งนี้ยังไม่ถึง ¥5,000 ก่อนภาษี หากรวมใบเสร็จร้านเดียวกันวันเดียวกันได้ ให้กรอกยอดรวมที่เข้าเงื่อนไข</div>':''}${!v.eligible?'<p class="note">ยังไม่หัก Tax-free จนกว่าจะยืนยันเงื่อนไขกับร้าน</p>':''}<p class="note">ยอดประมาณ ร้านอาจปัดเศษต่างกัน · งบจะหักยอดจ่ายจริงก่อน</p>`}catch{$('#shopResult').innerHTML='<p class="redtext">กรุณากรอกตัวเลขให้ถูกต้อง</p>';shopResult=null}}
function calcConvert(){const n=Number($('[name=convertAmount]')?.value||0),c=$('[name=convertCurrency]')?.value;$('#convertResult').innerHTML=`<span class="muted">ประมาณ</span><div class="big">${c==='JPY'?thb(n*T().rate):jpy(n/T().rate)}</div><p class="note">${esc(T().rateSource)} · 1 เยน = ${T().rate} บาท</p>`}
function tripView(){const t=T();return title('YOUR JOURNEYS','ทริปของฉัน','ข้อมูลส่วนตัวเก็บเฉพาะเบราว์เซอร์นี้',btn(icon('plus')+' สร้างทริป','newtrip','primary'))+`<div class="grid cols"><div><section class="card"><div class="cardhead"><h2>${esc(t.name)}</h2>${btn(icon('settings'),'tripsettings','small','aria-label="ตั้งค่าทริป"')}</div>${select('เลือกทริป','tripselect',S.trips.map(t=>[t.id,t.name]),t.id)}<div class="flex"><span class="pill">${t.city==='osaka'?'โอซาก้า':t.city==='both'?'โตเกียว + โอซาก้า':'โตเกียว'}</span><span class="pill">${formatDate(t.start)} – ${formatDate(t.end)}</span><span class="pill">${esc(t.people.join(' + '))}</span></div><p class="note">จุดนัดพบ: ${esc(t.meeting||'รอยืนยัน')}<br>ผู้ติดต่อ: ${esc(t.contact||'ยังไม่ระบุ')}</p></section><section class="card gap"><div class="cardhead"><h2>ที่พักและกระเป๋า</h2>${btn('เพิ่มที่พัก','hotel','small')}</div>${t.hotels.map(h=>`<div class="listitem"><span class="expenseicon">${icon('trip')}</span><div class="grow"><h3>${esc(h.name)}</h3><p>${formatDate(h.from)} – ${formatDate(h.to)}</p><p>เช็กอิน ${esc(h.checkin)} / เช็กเอาต์ ${esc(h.checkout)}</p><p class="overflow">${esc(h.address)}</p><p>ฝากกระเป๋า: ${esc(h.bag||'ยังไม่ยืนยัน')}</p><div class="flex">${link('แผนที่','https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(h.name+' '+h.address))}${h.phone?`<a class="btn" href="tel:${esc(h.phone.replace(/[^+0-9]/g,''))}">โทรที่พัก</a>`:''}${btn('แก้ไข','hotel','small',`data-id="${h.id}"`)}</div></div></div>`).join('')||'<div class="empty">ยังไม่ได้เพิ่มที่พัก</div>'}</section><section class="card gap"><div class="cardhead"><h2>เอกสารของทริป</h2>${btn(icon('plus')+' เพิ่มไฟล์','docadd','small')}</div><p class="note">รูปหรือ PDF สูงสุด 8 MB ต่อไฟล์ เก็บในเครื่องนี้ ไฟล์ไม่ได้อัปโหลดให้ผู้อื่น</p><div id="docs" class="filelist"></div></section></div><div>${readiness()}<section class="card gap"><h2>ออฟไลน์และสำรองข้อมูล</h2><div id="offlinePanel">${offlinePanel()}</div>${btn(icon('download')+' เตรียมใช้ออฟไลน์','offline','primary full')}<p class="note">iPhone: เปิดใน Safari แล้วแชร์ › เพิ่มไปยังหน้าจอโฮม<br>Android: เมนูเบราว์เซอร์ › เพิ่มลงหน้าจอหลัก / ติดตั้ง</p><div class="flex">${btn('ส่งออกสำรอง','export')}${btn('นำเข้าสำรอง','import')}</div><p class="note">${backupStatus()}<br>ล่าสุดที่สร้างไฟล์: ${esc(t.lastBackup||'ยังไม่ได้สำรอง')}<br>ไฟล์สำรองรวมทุกทริปและเอกสาร เก็บไว้เป็นส่วนตัว</p><div class="notice">สองเครื่องยังไม่ซิงก์อัตโนมัติ ใช้เครื่องหลักลงบัญชี แล้วส่งไฟล์สำรองเมื่อต้องการอัปเดตอีกเครื่อง</div></section></div></div>`}
function expenseModal(id='',prefill={}){const e=T().expenses.find(x=>x.id===id);if(e?.amount<0){modal('รายการรับคืน',`<p>${esc(e.title)} · ${jpy(e.amount)}</p>${btn('ลบรายการรับคืน','walletdelete','danger',`data-source="expense" data-id="${e.id}"`)}`);return}openWalletEntry('expense',id,prefill)}
function parseMoney(value){const s=String(value??'').trim().replace(/[๐-๙]/g,c=>String(c.charCodeAt(0)-3664)).replace(/[０-９]/g,c=>String(c.charCodeAt(0)-65296)).replace(/\s/g,'');return /^(?:\d+|\d{1,3}(?:,\d{3})+)(?:\.\d+)?$/.test(s)?Number(s.replace(/,/g,'')):NaN}
function expenseValues(v){const amount=parseMoney(v.amount),rate=parseMoney(v.rate),split=v.split||'half';if(!Number.isFinite(amount)||amount<=0||amount>999999999)throw Error('ใส่ยอดเงินมากกว่า 0 เยน เช่น 1,200');if(!Number.isFinite(rate)||rate<=0||rate>=10)throw Error('ตรวจเรทบาทต่อเยน เช่น 0.23');if(!/^\d{4}-\d{2}-\d{2}$/.test(v.date)||Number.isNaN(Date.parse(v.date)))throw Error('กรุณาเลือกวันที่ของรายการ');const mine=split==='mine'?amount:split==='other'?0:split==='half'?Math.round(amount*50)/100:parseMoney(v.mine);if(!Number.isFinite(mine)||mine<0||mine>amount)throw Error('ส่วนของฉันต้องอยู่ระหว่าง 0 ถึงยอดจ่ายรวม');return {amount,rate,mine,split,title:(v.title||'').trim()||v.category||'รายจ่าย'}}
function expensePreview(){const f=$('#expenseform');if(!f)return;const v=Object.fromEntries(new FormData(f)),n=parseMoney(v.amount)||0,r=parseMoney(v.rate)||0,m=v.split==='mine'?n:v.split==='other'?0:v.split==='half'?Math.round(n*50)/100:parseMoney(v.mine)||0;$('#customshare').hidden=v.split!=='custom';f.elements.mine.disabled=v.split!=='custom';$('#expensePreview').innerHTML=`<strong>≈ ${thb(n*r)}</strong><span>ส่วนของฉัน ${jpy(m)} ≈ ${thb(m*r)}</span>`}
function tripModal(isnew=false){let t=isnew?{...initialTrip(),name:'ทริปใหม่',events:[],hotels:[]}:T();formModal(isnew?'สร้างทริปใหม่':'ตั้งค่าทริป','tripform',`<input hidden name="isnew" value="${isnew?'1':'0'}">${field('ชื่อทริป','name',t.setupComplete===false?'':t.name,'text','required maxlength="100"')}${select('เมือง','city',[['tokyo','โตเกียว'],['osaka','โอซาก้า'],['both','ทั้งสองเมือง']],t.city)}<div class="grid two formgrid">${field('วันเริ่ม','start',t.setupComplete===false?'':t.start,'date','required')}${field('วันสิ้นสุด','end',t.setupComplete===false?'':t.end,'date','required')}${field('ชื่อของฉัน','person0',t.people[0],'text','required maxlength="40"')}${field('ชื่อผู้ร่วมทริป','person1',t.people[1],'text','required maxlength="40"')}</div>${select('สนามบินขาเข้า','airport',Object.entries(airports).map(([k,a])=>[k,a.name]),t.airport)}<div class="grid two formgrid">${field('งบส่วนตัวทั้งทริป (บาท)','budget',t.budget,'number','min="0" step="any" required')}${field('งบต่อวัน (บาท, 0 = ไม่ตั้ง)','daily',t.daily,'number','min="0" step="any" required')}</div>${field('เงินสดเยนเริ่มต้นของฉัน','cash',t.cash,'number','min="0" step="any" required')}<p class="note">เงินสดที่เพิ่มระหว่างทริปให้ใช้ “เพิ่มเงินสด” เพื่อไม่แก้ยอดเริ่มต้น</p>${field('จุดนัดพบ / สถานีที่นัด','meeting',t.meeting)}${field('ชื่อและช่องทางติดต่อผู้ที่มารับ','contact',t.contact)}${textarea('แผนสำรอง / หมายเหตุ','backup',t.backup)}`)}
function eventModal(id){const e=T().events.find(x=>x.id===id)||{date:day||T().start,time:'',title:'',note:'',done:false};formModal('แผนการเดินทาง','eventform',`<input hidden name="id" value="${id||''}">${field('กิจกรรม / สถานที่','title',e.title,'text','required maxlength="140"')}<div class="grid two formgrid">${field('วันที่','date',e.date,'date','required')}${field('เวลา (เว้นว่างได้)','time',e.time,'time')}</div>${textarea('วิธีเดินทาง / หมายเหตุ','note',e.note)}<label class="checkboxlabel"><input type="checkbox" name="done" ${e.done?'checked':''}>ทำแล้ว / ไปแล้ว</label>${id?btn('ลบแผนนี้','eventdelete','danger',`data-id="${id}"`):''}`)}
function hotelModal(id){const h=T().hotels.find(x=>x.id===id)||{name:'',address:'',phone:'',from:T().start,to:T().end,checkin:'15:00',checkout:'10:00',bag:''};formModal('ข้อมูลที่พัก','hotelform',`<input hidden name="id" value="${id||''}">${field('ชื่อโรงแรม','name',h.name,'text','required')}${textarea('ที่อยู่ / ที่อยู่ภาษาญี่ปุ่น','address',h.address)}${field('โทรศัพท์','phone',h.phone,'tel')}<div class="grid two formgrid">${field('วันเช็กอิน','from',h.from,'date','required')}${field('วันเช็กเอาต์','to',h.to,'date','required')}${field('เวลาเช็กอิน','checkin',h.checkin,'time')}${field('เวลาเช็กเอาต์','checkout',h.checkout,'time')}</div>${textarea('ฝากกระเป๋าที่ไหน / เวลารับ / สถานะยืนยัน','bag',h.bag)}${id?btn('ลบที่พัก','hoteldelete','danger',`data-id="${id}"`):''}`)}
function lost(){const t=T();modal('ฉันต้องการความช่วยเหลือ',`<p class="note">เลือกปลายทาง แล้วเปิดหน้านี้ให้เจ้าหน้าที่อ่าน</p>${select('ปลายทาง','lostDestination',[['meeting','จุดนัดพบ'],...t.hotels.map(h=>[h.id,h.name])],t.hotels[0]?.id||'meeting')}<div id="lostText"></div>${btn('ขยายข้อความ','lostexpand','primary full')}<p class="note">ผู้ติดต่อ: ${esc(t.contact||'ยังไม่ได้ระบุ')}<br>แผนสำรอง: ${esc(t.backup||'ยังไม่ได้ระบุ')}</p>`);updateLost()}
function updateLost(){let id=$('[name=lostDestination]').value,h=T().hotels.find(x=>x.id===id),dest=h?h.name+'\n'+h.address:T().meeting;$('#lostText').innerHTML=`<div class="valuecard"><p class="jp">ここへ行きたいです。</p><p>ฉันต้องการไปที่นี่</p><p class="overflow" id="destinationText">${esc(dest||'ยังไม่ระบุปลายทาง กรุณาเพิ่มข้อมูลทริปก่อน')}</p></div><p>${dest?link('เปิดแผนที่','https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(dest)):''}</p>`}
async function fetchRate(){toast('กำลังอัปเดตเรทอ้างอิง…');try{const r=await fetch('https://api.frankfurter.dev/v2/rate/JPY/THB',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw 0;const d=await r.json();if(!(d.rate>0&&d.rate<10)||!d.date)throw 0;T().rate=d.rate;T().rateSource='Frankfurter • เรทอ้างอิงรายวัน';T().rateDate=d.date;save();render();toast('อัปเดตแล้ว วันที่ข้อมูล '+d.date)}catch{toast('อัปเดตไม่ได้ ใช้เรทที่บันทึกไว้ต่อ หรือกำหนดเรทเองได้')}}
const dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('tabi-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function dbCall(action,data){const db=await dbPromise;return new Promise((resolve,reject)=>{const tx=db.transaction('files',action==='getAll'?'readonly':'readwrite'),s=tx.objectStore('files'),r=action==='getAll'?s.getAll():s[action](data);let out;r.onsuccess=()=>out=r.result;tx.oncomplete=()=>resolve(out);tx.onerror=()=>reject(tx.error)})}
async function renderDocs(){const t=T();try{const files=(await dbCall('getAll')).filter(x=>x.trip===t.id);if(!$('#docs')||t.id!==T().id)return;$('#docs').innerHTML=files.map(f=>`<div class="row"><div><strong>${esc(f.name)}</strong><p>${(f.data.length/1024/1.33).toFixed(0)} KB · ในเครื่อง</p></div><div class="flex">${btn('เปิด','docopen','small',`data-id="${f.id}"`)}${btn('ลบ','docdelete','small danger',`data-id="${f.id}"`)}</div></div>`).join('')||'<div class="empty">เพิ่มใบจอง รูป หรือ PDF เพื่อเปิดเมื่อไม่มีเน็ต</div>'}catch{if($('#docs'))$('#docs').textContent='พื้นที่เก็บไฟล์ไม่พร้อมใช้งานในเบราว์เซอร์นี้'}}
async function exportData(){try{const files=await dbCall('getAll');T().lastBackup=new Date().toLocaleString('th-TH');S.backupSignature=backupSignature();save();const blob=new Blob([JSON.stringify({app:'tabi',version:1,state:S,files})],{type:'application/json'});downloadBlob(blob,'ichi-japan-backup-'+today()+'.json');render();toast('สร้างไฟล์สำรองแล้ว เลือกบันทึกไฟล์ให้เรียบร้อย แอปตรวจไม่ได้ว่าคุณเก็บไฟล์แล้วหรือยัง')}catch{toast('สำรองไม่สำเร็จ กรุณาลองใหม่')}}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000)}
function validateImport(d){if(d.app!=='tabi'||d.version!==1||d.state?.version!==1||!Array.isArray(d.state.trips)||!d.state.trips.length||!Array.isArray(d.files))throw Error('รูปแบบไฟล์ไม่ถูกต้อง');for(const t of d.state.trips){if(!/^[a-f0-9-]{36}$/.test(t.id))throw Error('รหัสทริปไม่ถูกต้อง');for(const k of ['events','hotels','expenses','moves','trash']){if(!Array.isArray(t[k]))throw Error('ข้อมูลไม่ครบ');for(const x of t[k])if(!/^[a-f0-9-]{36}$/.test(x.id))throw Error('รหัสรายการไม่ถูกต้อง')}if(typeof t.id!=='string'||typeof t.name!=='string'||!Array.isArray(t.people)||(t.people.length<1||t.people.length>20)||!t.people.every(p=>typeof p==='string')||!/^\d{4}-\d{2}-\d{2}$/.test(t.start)||!/^\d{4}-\d{2}-\d{2}$/.test(t.end)||t.end<t.start||!Number.isFinite(t.rate)||t.rate<=0||!Number.isFinite(t.budget)||!Number.isFinite(t.cash)||!airports[t.airport])throw Error('ข้อมูลทริปไม่ถูกต้อง');for(const k of ['events','hotels','expenses','moves','trash'])if(!Array.isArray(t[k]))throw Error('ข้อมูลไม่ครบ');for(const e of t.expenses)if(!['amount','mine','rate'].every(k=>Number.isFinite(e[k]))||e.rate<=0||!['me','other'].includes(e.payer)||!['cash','card'].includes(e.method))throw Error('รายการเงินไม่ถูกต้อง');for(const m of t.moves)if(!Number.isFinite(m.amount)||!['settle','cash','income'].includes(m.kind))throw Error('รายการโอนไม่ถูกต้อง');if(!t.checks||!t.step)throw Error('ข้อมูลไม่ครบ')}for(const f of d.files)if(!/^[a-f0-9-]{36}$/.test(f.id)||typeof f.id!=='string'||typeof f.name!=='string'||typeof f.trip!=='string'||!/^data:(image\/(png|jpeg|webp|gif|heic|heif)|application\/pdf);base64,/i.test(f.data))throw Error('ไฟล์แนบไม่รองรับ');return d}
async function prepareOffline(){await offlineRequest(true)}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button,[data-page]');if(!b)return;if(b.type!=='submit')ev.preventDefault();if(b.dataset.page){go(b.dataset.page);return}if(b.dataset.day){day=b.dataset.day;render();return}if(b.dataset.money){moneyTab=b.dataset.money;render();return}if(b.dataset.travel){travelTab=b.dataset.travel;render();return}if(b.dataset.airport){guideAirport=b.dataset.airport;render();return}if(b.dataset.step!==undefined){T().step[guideAirport||T().airport]=Number(b.dataset.step);save();render();return}const id=b.dataset.id,a=b.dataset.action,t=T();switch(a){case'close':$('#modal').close();break;case'expense':expenseModal(id);break;case'tripsettings':tripModal();break;case'newtrip':tripModal(true);break;case'eventedit':eventModal(id);break;case'hotel':hotelModal(id);break;case'immigration':travelTab='immigration';go('travel');break;case'manners':travelTab='manners';go('travel');break;case'guide':travelTab='guide';go('travel');break;case'phrases':travelTab='phrases';go('travel');break;case'shop':moneyTab='shop';go('money');break;case'phrase':phraseModal(Number(b.dataset.index));break;case'lost':lost();break;case'lostexpand':{const text=$('#destinationText').textContent;$('#modal').close();modal('แสดงให้เจ้าหน้าที่อ่าน',`<div class="fullscreenjp"><p class="jp">ここへ行きたいです。</p><p class="overflow">${esc(text)}</p><p class="muted">ฉันต้องการไปที่นี่</p></div>`);break}case'stepback':case'stepnext':{let k=guideAirport||t.airport;const current=t.step[k]||0;t.step[k]=Math.max(0,Math.min(5,current+(a==='stepnext'?1:-1)));save();if(current===5&&a==='stepnext'){travelTab='routes';routeCity=k==='kix'?'osaka':'tokyo';toast('ต่อไป เลือกการเดินทางให้ตรงปลายทาง')}render();break}case'ratefetch':b.disabled=true;await fetchRate();b.disabled=false;break;case'rateset':formModal('ตั้งเรทของคุณ','rateform',field('บาทต่อ 1 เยน','rate',t.rate,'number','min="0.000001" max="10" step="any" required'));break;case'cash':openWalletEntry('cash');break;case'settle':openWalletEntry('settle');break;case'refund':{const expenses=t.expenses.filter(e=>e.amount>0);if(!expenses.length){toast('เพิ่มค่าใช้จ่ายต้นทางก่อนบันทึกรับคืน');break}formModal('รับคืนจากร้าน / Tax-free','refundform',`${select('รายการต้นทาง','original',expenses.map(e=>[e.id,e.title+' '+nativeMoney(e)]),expenses[0].id)}${field('จำนวนที่คืน (สกุลเงินเดียวกับรายการต้นทาง)','amount','','number','min="0.01" step="0.01" required')}${field('วันที่รับคืน','date',today(),'date','required')}${select('รับคืนผ่าน','method',[['cash','เงินสด'],['card','บัตร / โอน']],'card')}<p class="note">คืนเข้าคนที่จ่ายรายการเดิม และลดส่วนแบ่งตามสัดส่วนเดิม หากต่างจากนี้ให้ปรับการคืนเงินระหว่างกันเพิ่มเติม</p>`);break}case'expdelete':{if(t.expenses.some(e=>e.original===id)){toast('ลบรายการคืนเงินที่เกี่ยวข้องก่อนแก้หรือลบต้นทาง');break}if(confirm('ย้ายรายการนี้ไปถังขยะ?')){const e=t.expenses.find(e=>e.id===id);t.trash.push(e);t.expenses=t.expenses.filter(e=>e.id!==id);save();$('#modal').close();render();toast('ย้ายไปถังขยะแล้ว กู้คืนได้')}break}case'trash':modal('รายการที่ลบ',t.trash.length?t.trash.map(e=>`<div class="row"><span>${esc(e.title)} · ${jpy(e.amount)}</span>${btn('กู้คืน','restore','small',`data-id="${e.id}"`)}</div>`).join(''):'<p class="note">ไม่มีรายการที่ลบ</p>');break;case'restore':{const e=t.trash.find(e=>e.id===id);if(e){t.expenses.push(e);t.trash=t.trash.filter(e=>e.id!==id);save();$('#modal').close();render();toast('กู้คืนแล้ว')}break}case'movedelete':if(confirm('ลบการเคลื่อนไหวเงินนี้?')){t.moves=t.moves.filter(m=>m.id!==id);save();render()}break;case'eventdelete':if(confirm('ลบแผนนี้?')){t.events=t.events.filter(e=>e.id!==id);save();$('#modal').close();render()}break;case'hoteldelete':if(confirm('ลบที่พักนี้?')){t.hotels=t.hotels.filter(e=>e.id!==id);save();$('#modal').close();render()}break;case'shopbuy':if(shopResult?.pay>0)expenseModal('',{title:'ซื้อของ',category:'ซื้อของ',amount:Math.round(shopResult.pay*100)/100,split:'mine'});else toast('กรอกราคาที่ต้องจ่ายก่อน');break;case'offline':b.disabled=true;await prepareOffline();b.disabled=false;break;case'export':await exportData();break;case'import':$('#importfile').click();break;case'docadd':$('#docfile').click();break;case'docopen':try{const f=(await dbCall('getAll')).find(f=>f.id===id);if(f){const res=await fetch(f.data),blob=await res.blob();downloadBlob(blob,f.name)}}catch{toast('เปิดไฟล์ไม่สำเร็จ')}break;case'docdelete':if(confirm('ลบไฟล์นี้จากเครื่อง?')){await dbCall('delete',id);S.docRevision=Date.now();save();renderDocs()}break;}});
document.addEventListener('input',ev=>{if(ev.target.closest('#shopform'))calcShop();if(ev.target.closest('#expenseform'))expensePreview();if(['convertAmount','convertCurrency'].includes(ev.target.name))calcConvert()});
document.addEventListener('change',ev=>{let e=ev.target;if(e.dataset.check){T().checks[e.dataset.check]=e.checked;save();render()}if(e.name==='tripselect'){S.current=e.value;day='';guideAirport='';save();render()}if(e.name==='lostDestination')updateLost();if(e.closest('#shopform'))calcShop();if(e.closest('#expenseform'))expensePreview();if(e.name==='convertCurrency')calcConvert()});
document.addEventListener('submit',ev=>{ev.preventDefault();const f=ev.target,v=Object.fromEntries(new FormData(f)),t=T(),before=JSON.stringify(S);try{switch(f.getAttribute('id')){case'expenseform':{const data=expenseValues(v),n=data.amount,r=data.rate,mine=data.mine;v.title=data.title;v.split=data.split;if(v.id&&t.expenses.some(e=>e.original===v.id))throw Error('รายการนี้มีเงินคืนแล้ว กรุณาลบเงินคืนก่อนแก้ต้นทาง');const duplicate=t.expenses.some(e=>e.id!==v.id&&e.title===v.title&&e.amount===n&&e.date===v.date&&e.payer===v.payer);if(duplicate&&!confirm('พบรายการชื่อและยอดเดียวกันในวันเดียวกัน ต้องการบันทึกซ้ำไหม?'))return;const e={id:v.id||uid(),title:v.title.trim(),amount:n,mine,rate:r,date:v.date,category:v.category,payer:v.payer,method:v.method,split:v.split};let i=t.expenses.findIndex(x=>x.id===v.id);if(i>=0)t.expenses[i]=e;else t.expenses.push(e);break}case'tripform':{if(v.end<v.start||(new Date(v.end)-new Date(v.start))/864e5>89)throw Error('วันสิ้นสุดต้องไม่ก่อนวันเริ่ม และทริปไม่เกิน 90 วัน');let dest=v.isnew==='1'?{...initialTrip(),events:[],hotels:[]}:t;Object.assign(dest,{setupComplete:true,name:v.name.trim(),city:v.city,start:v.start,end:v.end,people:[v.person0.trim(),v.person1.trim()],airport:v.airport,budget:Number(v.budget),daily:Number(v.daily),cash:Number(v.cash),meeting:v.meeting,contact:v.contact,backup:v.backup});if(v.isnew==='1'){S.trips.push(dest);S.current=dest.id}day='';guideAirport='';break}case'eventform':{const e={...(t.events.find(x=>x.id===v.id)||{}),id:v.id||uid(),title:v.title,date:v.date,time:v.time,note:v.note,done:!!v.done};let i=t.events.findIndex(e=>e.id===v.id);if(i>=0)t.events[i]=e;else t.events.push(e);if(Math.abs((new Date(v.date)-new Date(t.start))/864e5)>89)throw Error('แผนต้องอยู่ภายในช่วง 90 วันของทริป');if(v.date<t.start||v.date>t.end){t.start=v.date<t.start?v.date:t.start;t.end=v.date>t.end?v.date:t.end}day=v.date;break}case'hotelform':{if(v.to<v.from)throw Error('วันเช็กเอาต์ต้องไม่ก่อนวันเช็กอิน');const h={...v,id:v.id||uid()};let i=t.hotels.findIndex(e=>e.id===v.id);if(i>=0)t.hotels[i]=h;else t.hotels.push(h);break}case'rateform':{const r=Number(v.rate);if(!(r>0&&r<10))throw Error('เรทไม่ถูกต้อง');t.rate=r;t.rateDate=today();t.rateSource='เรทที่กำหนดเอง';break}case'moveform':{let n=Number(v.amount);if(!Number.isFinite(n)||n===0)throw Error('จำนวนเงินไม่ถูกต้อง');if(v.kind==='settle')n=Math.abs(n)*(v.direction==='out'?-1:1);t.moves.push({id:uid(),kind:v.kind,amount:n,date:v.date,method:v.method||'cash'});break}case'refundform':{const e=t.expenses.find(e=>e.id===v.original),n=Number(v.amount)/(e.currency==='THB'?e.rate:1),refunded=-t.expenses.filter(x=>x.original===e.id).reduce((a,x)=>a+x.amount,0);if(!(n>0)||n>e.amount-refunded+.001)throw Error('ยอดคืนรวมต้องไม่เกินยอดจ่ายต้นทาง');t.expenses.push({...e,id:uid(),original:e.id,title:'รับคืน · '+e.title,amount:-n,shares:refundShares(e,n,t),mine:refundShares(e,n,t)[0]||0,date:v.date,method:v.method});break}default:return}if(!save())throw Error('พื้นที่บันทึกไม่พร้อม ข้อมูลยังไม่ถูกบันทึก ลองส่งออกสำรองหรือเปิดในเบราว์เซอร์หลัก');$('#modal').close();if(f.getAttribute('id')==='expenseform'){page='money';moneyTab='ledger';location.hash='money'}render();toast('บันทึกแล้วในเครื่องนี้')}catch(e){S=JSON.parse(before);toast(e.message||'บันทึกไม่สำเร็จ')}});
$('#docfile').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;if(f.size>8*1024*1024){toast('ไฟล์ต้องไม่เกิน 8 MB');return}if(!/^(image\/(png|jpeg|webp|gif|heic|heif)|application\/pdf)$/.test(f.type)){toast('รองรับภาพ PNG, JPG, WEBP, GIF, HEIC และ PDF');return}const trip=T().id;try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});await dbCall('put',{id:uid(),trip,name:f.name,type:f.type,data});S.docRevision=Date.now();save();renderDocs();toast('เก็บไฟล์ไว้ในเครื่องแล้ว')}catch{toast('เก็บไฟล์ไม่ได้ พื้นที่อาจไม่เพียงพอ')}});
$('#importfile').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>100*1024*1024)throw Error('ไฟล์สำรองใหญ่เกิน 100 MB');const d=validateImport(JSON.parse(await f.text()));if(!confirm('นำเข้าจะรวมทริปใหม่ และแทนที่ทริปที่มีรหัสเดียวกัน ควรสำรองเครื่องนี้ก่อน ดำเนินการต่อไหม?'))return;for(const x of d.files)await dbCall('put',x);for(const t of d.state.trips){const i=S.trips.findIndex(x=>x.id===t.id);if(i>=0)S.trips[i]=t;else S.trips.push(t)}S.current=d.state.current;save();day='';guideAirport='';render();toast('นำเข้าสำเร็จ')}catch(err){toast(err.message||'นำเข้าไม่สำเร็จ')}});
