const validBooking=new Set(Object.keys(bookingLabels));
const dayEvents=(date,source=T().events)=>source.filter(e=>e.date===date).slice().sort((a,b)=>{const ao=Number.isFinite(a.order)?a.order:1e9,bo=Number.isFinite(b.order)?b.order:1e9;if(ao!==bo)return ao-bo;return String(a.time||'99:99').localeCompare(String(b.time||'99:99'))||String(a.title).localeCompare(String(b.title))});
function resequence(date){dayEvents(date).forEach((e,i)=>e.order=i)}
function googleLeg(a,b){const q=x=>encodeURIComponent(String(x||'').trim());return `https://www.google.com/maps/dir/?api=1&origin=${q(a.title)}&destination=${q(b.title)}&travelmode=transit`}
function eventRows109(events){const list=events.slice().sort((a,b)=>{const ao=Number.isFinite(a.order)?a.order:1e9,bo=Number.isFinite(b.order)?b.order:1e9;if(ao!==bo)return ao-bo;return String(a.time||'99:99').localeCompare(String(b.time||'99:99'))});if(!list.length)return `<div class="empty">วันนี้ยังไม่มีแผน<br>เพิ่มสถานที่หรือเวลานัดหมายได้เลย</div>`;return list.map((e,i)=>{const next=list[i+1],status=validBooking.has(e.bookingStatus)?e.bookingStatus:'planned',route=e.routeToNext&&next&&e.routeToNext.destinationId===next.id?e.routeToNext:null;return `<article class="event event-card ${e.done?'done':''}"><time>${esc(e.time||'—')}</time><span class="dot"></span><div class="event-main"><div class="event-heading"><h3>${esc(e.title)}</h3><div class="event-state"><span class="booking-chip booking-${status}">${bookingLabels[status]}</span>${e.entryTime?`<span class="entry-chip">เข้า ${esc(e.entryTime)}</span>`:''}${e.done?'<span class="entry-chip done-chip">ไปแล้ว ✓</span>':''}</div></div>${e.note?`<p>${esc(e.note)}</p>`:''}${route?`<div class="leg-note"><b>วิธีไปจุดถัดไป</b><span>${esc(route.text)}</span></div>`:''}${e.ticketFileId?`<div class="ticket-line">🎟 ${esc(e.ticketName||'ตั๋วที่แนบไว้')} ${btn('เปิดตั๋ว','docopen','small',`data-id="${esc(e.ticketFileId)}"`)}</div>`:''}<div class="event-route-actions">${next?`<a class="btn small route-next" data-online-route href="${googleLeg(e,next)}" target="_blank" rel="noopener noreferrer">จากจุดนี้ไปจุดถัดไป ↗</a>${btn(route?'แก้วิธีเดินทาง':'บันทึกวิธีเดินทาง','routeedit','small',`data-id="${esc(e.id)}" data-next="${esc(next.id)}"`)}`:''}${e.discoverId?`<button type="button" class="btn small" data-discover="detail" data-id="${esc(e.discoverId)}">📍 สถานที่</button>`:''}</div></div><div class="event-mobile-controls">${btn('↑','eventup','small',`data-id="${esc(e.id)}" aria-label="เลื่อน ${esc(e.title)} ขึ้น" ${i===0?'disabled':''}`)}${btn('↓','eventdown','small',`data-id="${esc(e.id)}" aria-label="เลื่อน ${esc(e.title)} ลง" ${i===list.length-1?'disabled':''}`)}${btn('ย้ายวัน','eventmove','small',`data-id="${esc(e.id)}"`)}${btn(e.done?'ยังไม่ไป':'ไปแล้ว ✓','eventdone','small',`data-id="${esc(e.id)}"`)}${btn(icon('edit'),'eventedit','small',`data-id="${esc(e.id)}" aria-label="แก้ไข ${esc(e.title)}"`)}</div></article>`}).join('')}
eventRows=eventRows109;
planView=function(){const t=T(),ds=dates(t);if(!ds.includes(day))day=ds[0];const list=dayEvents(day);return title('ITINERARY','แผนเที่ยวของเรา','เรียงด้วยปุ่มบนมือถือ · เก็บเส้นทาง ตั๋ว และสถานะการจองไว้ในวันเดียวกัน',btn(icon('plus')+' เพิ่มแผน','eventedit','primary'))+`<div class="tabs plan-date-tabs">${ds.map(d=>`<button class="tab datebtn ${d===day?'active':''}" data-day="${d}">${new Intl.DateTimeFormat('th',{weekday:'short'}).format(new Date(d+'T12:00:00'))}<b>${Number(d.slice(-2))}</b></button>`).join('')}</div><div class="grid cols plan-layout"><div class="card plan-card"><div class="cardhead"><div><h2>${formatDate(day)}</h2><p class="note">${list.length} จุด · กด ↑ ↓ เพื่อจัดลำดับโดยไม่ต้องลาก</p></div><span class="pill">บันทึกในเครื่อง</span></div>${eventRows109(list)}</div><div><div class="card booking-legend"><h2>สถานะการจอง</h2><div class="booking-flow"><span>อยากไป</span><i>→</i><span>ใส่แผนแล้ว</span><i>→</i><span>ต้องจอง</span><i>→</i><span>จองแล้ว</span></div><p class="note">รายการ “อยากไป” เก็บจากหน้า ที่ควรไป · เมื่อใส่ลงวันแล้วเลือกสถานะต่อได้ในปุ่มแก้ไข</p></div><div class="card gap"><h2>สิ่งที่ยังรอยืนยัน</h2><p class="note">${t.meeting?'จุดนัดพบ: '+esc(t.meeting):'จุดนัดพบหลังออกจากสนามบินยังไม่ระบุ'}</p>${btn('เพิ่มหรือแก้ไขข้อมูลทริป','tripsettings','full')}</div><div class="card gap"><h2>เผื่อแผนเปลี่ยน</h2><p>${esc(t.backup||'บันทึกวิธีติดต่อ จุดนัดสำรอง หรือสิ่งที่จะทำหากพลาดรถไว้ที่นี่')}</p>${btn('แก้ไขแผนสำรอง','tripsettings')}</div></div></div>`+placesView()};
eventModal=function(id){const e=T().events.find(x=>x.id===id)||{date:day||T().start,time:'',title:'',note:'',done:false,bookingStatus:'planned',entryTime:''},status=validBooking.has(e.bookingStatus)?e.bookingStatus:'planned';formModal('แผนการเดินทาง','eventform',`<input hidden name="id" value="${esc(id||'')}">${field('กิจกรรม / สถานที่','title',e.title,'text','required maxlength="140"')}<div class="grid two formgrid">${field('วันที่','date',e.date,'date','required')}${field('เวลาในแผน (เว้นว่างได้)','time',e.time,'time')}</div>${select('สถานะการจอง','bookingStatus',Object.entries(bookingLabels).map(([v,l])=>[v,l]),status)}${field('เวลาเข้าชมตามตั๋ว (ถ้ามี)','entryTime',e.entryTime||'','time')}${textarea('หมายเหตุสถานที่','note',e.note||'')}<div class="ticket-editor"><b>🎟 ตั๋ว / ใบจอง</b>${id?(e.ticketFileId?`<p>${esc(e.ticketName||'แนบตั๋วแล้ว')}</p><div class="flex">${btn('เปิดตั๋ว','docopen','small',`data-id="${esc(e.ticketFileId)}"`)}${btn('เปลี่ยนไฟล์','ticketadd','small',`data-id="${esc(id)}"`)}${btn('เอาตั๋วออก','ticketremove','small danger',`data-id="${esc(id)}"`)}</div>`:`<p class="note">แนบภาพหรือ PDF สูงสุด 8 MB เพื่อเปิดจากเครื่องนี้ได้</p>${btn('แนบตั๋ว','ticketadd','small',`data-id="${esc(id)}"`)}`):'<p class="note">บันทึกแผนก่อน 1 ครั้ง แล้วเปิดแก้ไขเพื่อแนบตั๋ว</p>'}</div><label class="checkboxlabel"><input type="checkbox" name="done" ${e.done?'checked':''}>ทำแล้ว / ไปแล้ว</label>${id?btn('ลบแผนนี้','eventdelete','danger',`data-id="${esc(id)}"`):''}`)};
