function routeEdit(id,nextId){const e=T().events.find(x=>x.id===id),n=T().events.find(x=>x.id===nextId);if(!e||!n)return;const current=e.routeToNext?.destinationId===n.id?e.routeToNext.text:'';formModal('วิธีเดินทางไปจุดถัดไป','routeform',`<input type="hidden" name="id" value="${esc(e.id)}"><input type="hidden" name="next" value="${esc(n.id)}"><p><b>${esc(e.title)}</b> → <b>${esc(n.title)}</b></p>${textarea('บันทึกไว้อ่านออฟไลน์ เช่น JR Yamanote → ลง Shibuya → ทางออก Hachiko','text',current)}<p class="note">ปุ่ม Google Maps ใช้เน็ต แต่ข้อความที่บันทึกตรงนี้เปิดอ่านออฟไลน์ได้</p>`)}
function moveEvent(id,dir){const e=T().events.find(x=>x.id===id);if(!e)return;const list=dayEvents(e.date);const i=list.findIndex(x=>x.id===id),j=i+dir;if(i<0||j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];list.forEach((x,k)=>x.order=k);list.forEach(x=>x.routeToNext=null);save();render()}
document.addEventListener('click',async e=>{const online=e.target.closest('[data-online-route]');if(online&&!navigator.onLine){e.preventDefault();e.stopImmediatePropagation();toast('Google Maps ต้องใช้อินเทอร์เน็ต · วิธีเดินทางที่บันทึกไว้อ่านออฟไลน์ได้');return}const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(!['eventup','eventdown','eventmove','eventdone','routeedit','ticketadd','ticketremove','eventdelete','docdelete'].includes(a))return;e.preventDefault();e.stopImmediatePropagation();const id=b.dataset.id;if(a==='docdelete'){if(confirm('ลบไฟล์นี้จากเครื่อง?')){const refs=T().events.filter(x=>x.ticketFileId===id);await dbCall('delete',id);refs.forEach(x=>{delete x.ticketFileId;delete x.ticketName});S.docRevision=Date.now();save();render();toast(refs.length?'ลบไฟล์และนำออกจากแผนแล้ว':'ลบไฟล์แล้ว')}return}const ev=T().events.find(x=>x.id===id);if(!ev)return;if(a==='eventup'||a==='eventdown'){moveEvent(id,a==='eventup'?-1:1);return}if(a==='eventdone'){ev.done=!ev.done;save();render();return}if(a==='eventmove'){formModal('ย้ายไปวันอื่น','eventmoveform',`<input type="hidden" name="id" value="${esc(id)}">${select('เลือกวัน','date',dates(T()).map(d=>[d,fullDate109(d)]),ev.date)}<p class="note">รายการจะถูกวางท้ายวันใหม่ แล้วใช้ ↑ ↓ จัดตำแหน่งต่อได้</p>`);return}if(a==='routeedit'){routeEdit(id,b.dataset.next);return}if(a==='ticketadd'){pendingTicketEvent=id;$('#ticketfile').click();return}if(a==='ticketremove'){if(ev.ticketFileId)await dbCall('delete',ev.ticketFileId).catch(()=>{});delete ev.ticketFileId;delete ev.ticketName;save();$('#modal').close();render();toast('เอาตั๋วออกแล้ว');return}if(a==='eventdelete'){if(confirm('ลบแผนนี้?')){if(ev.ticketFileId)await dbCall('delete',ev.ticketFileId).catch(()=>{});T().events=T().events.filter(x=>x.id!==id);resequence(ev.date);save();$('#modal').close();render()}}},true);
document.addEventListener('submit',e=>{const f=e.target,id=f.getAttribute('id');if(!['eventform','routeform','eventmoveform'].includes(id))return;e.preventDefault();e.stopImmediatePropagation();const v=Object.fromEntries(new FormData(f)),t=T();try{if(id==='routeform'){const ev=t.events.find(x=>x.id===v.id),n=t.events.find(x=>x.id===v.next);if(!ev||!n)throw Error('ไม่พบจุดในแผน');ev.routeToNext={destinationId:n.id,text:String(v.text||'').trim()};save();$('#modal').close();render();toast('บันทึกวิธีเดินทางไว้ออฟไลน์แล้ว');return}if(id==='eventmoveform'){const ev=t.events.find(x=>x.id===v.id);if(!ev||!dates(t).includes(v.date))throw Error('เลือกวันในทริป');const old=ev.date;ev.date=v.date;ev.order=dayEvents(v.date).length;ev.routeToNext=null;resequence(old);resequence(v.date);day=v.date;save();$('#modal').close();render();toast('ย้ายวันแล้ว');return}const old=t.events.find(x=>x.id===v.id),wasDate=old?.date;const state=validBooking.has(v.bookingStatus)?v.bookingStatus:'planned';const ev={...(old||{}),id:v.id||uid(),title:String(v.title||'').trim(),date:v.date,time:v.time||'',note:v.note||'',done:!!v.done,bookingStatus:state,entryTime:v.entryTime||''};if(!ev.title)throw Error('กรอกกิจกรรม / สถานที่');if(Math.abs((new Date(v.date)-new Date(t.start))/864e5)>89)throw Error('แผนต้องอยู่ภายในช่วง 90 วันของทริป');if(v.date<t.start||v.date>t.end){t.start=v.date<t.start?v.date:t.start;t.end=v.date>t.end?v.date:t.end}if(old){Object.assign(old,ev);if(wasDate!==v.date){old.order=dayEvents(v.date).length;old.routeToNext=null;resequence(wasDate)}}else{ev.order=dayEvents(v.date).length;t.events.push(ev)}resequence(v.date);day=v.date;if(!save())throw Error('พื้นที่บันทึกไม่พร้อม');$('#modal').close();render();toast('บันทึกแผนแล้ว')}catch(err){toast(err.message||'บันทึกไม่สำเร็จ')}},true);
$('#ticketfile')?.addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';const eventId=pendingTicketEvent;pendingTicketEvent='';if(!f||!eventId)return;if(f.size>8*1024*1024){toast('ไฟล์ต้องไม่เกิน 8 MB');return}if(!/^(image\/(png|jpeg|webp|gif|heic|heif)|application\/pdf)$/.test(f.type)){toast('รองรับภาพหรือ PDF');return}const ev=T().events.find(x=>x.id===eventId);if(!ev)return;try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)});if(ev.ticketFileId)await dbCall('delete',ev.ticketFileId).catch(()=>{});const fileId=uid();await dbCall('put',{id:fileId,trip:T().id,event:eventId,kind:'ticket',name:f.name,type:f.type,data});ev.ticketFileId=fileId;ev.ticketName=f.name;S.docRevision=Date.now();save();$('#modal').close();render();toast('แนบตั๋วไว้ในเครื่องแล้ว')}catch{toast('เก็บตั๋วไม่ได้ พื้นที่อาจไม่เพียงพอ')}});


