function focusDateLabel130(d,t=T()){
 const n=today(),diff=isoDiffDays(d,n);if(d===n)return 'วันนี้';if(d===t.start&&n<t.start)return `วันแรกของทริป · อีก ${Math.max(0,diff)} วัน`;if(diff===1)return 'พรุ่งนี้';if(diff>1)return `อีก ${diff} วัน`;return formatDate(d);
}
function bookingState130(e){return validBooking.has(e.bookingStatus)?e.bookingStatus:(e.bookingStatus==='needs-booking'?'need':'planned')}
function bookingStats130(t=T()){
 const rows=(t.events||[]).slice().sort((a,b)=>(a.date+(a.time||'99:99')).localeCompare(b.date+(b.time||'99:99')));
 const groups={wish:[],planned:[],need:[],booked:[]};rows.forEach(e=>groups[bookingState130(e)].push(e));
 const suggested=rows.filter(e=>{const meta=e.discoverId?discover.entrySummary(e.discoverId):null;return bookingState130(e)==='planned'&&meta?.reservationLabel&&/จอง|reserve|reservation/i.test(meta.reservationLabel)&&!/ไม่จำเป็น|walk-in/i.test(meta.reservationLabel)});
 return {groups,suggested,tickets:rows.filter(e=>e.ticketFileId)};
}
function routeStats130(date,source=T().events){
 const list=dayEvents(date,source),legs=[];for(let i=0;i<list.length-1;i++){const a=list[i],b=list[i+1],saved=a.routeToNext?.destinationId===b.id&&String(a.routeToNext?.text||'').trim();legs.push({a,b,saved:!!saved,text:saved?a.routeToNext.text:''})}
 return {list,legs,total:legs.length,saved:legs.filter(x=>x.saved).length,missing:legs.filter(x=>!x.saved).length};
}
function budgetPlan130(t=T()){
 const p=t.budgetPlan||{},keys=['flight','hotel','transport','food','attractions','shopping','buffer'];const total=keys.reduce((n,k)=>n+safeNumber(p[k]),0);return {...p,total};
}
function dataHealth130(events=[]){return discover.freshnessForIds(events.map(e=>e.discoverId).filter(Boolean))}
function freshnessBadge130(f){if(!f)return '<span class="fresh-chip stale">ไม่มีวันที่ตรวจ</span>';return `<span class="fresh-chip ${esc(f.cls)}">${esc(f.label)}</span>`}
function moneyProgress130(){const t=T(),plan=budgetPlan130(t),actual=totals(t).cost,ceiling=plan.total||t.budget||0,pct=ceiling?Math.min(100,actual/ceiling*100):0;return {plan,actual,ceiling,pct,remaining:ceiling-actual}}
function dayAlternative130(date){return (T().dayAlternatives||{})[date]||{rain:'',tired:'',extra:''}}

