function budgetPlanner130(){const p=budgetPlan130();formModal('วางงบทริป','budgetplanform',`<p class="note">กรอกเป็นเงินบาทต่อทั้งทริป ใช้เป็นแผนเทียบกับรายจ่ายจริง ไม่สร้างรายการจ่ายให้อัตโนมัติ</p><div class="grid two formgrid">${field('✈️ เครื่องบิน','flight',p.flight||'','number','min="0" step="1"')}${field('🏨 ที่พัก','hotel',p.hotel||'','number','min="0" step="1"')}${field('🚆 เดินทาง','transport',p.transport||'','number','min="0" step="1"')}${field('🍜 อาหาร','food',p.food||'','number','min="0" step="1"')}${field('🎟 ที่เที่ยว / ตั๋ว','attractions',p.attractions||'','number','min="0" step="1"')}${field('🛍 ช้อปปิ้ง','shopping',p.shopping||'','number','min="0" step="1"')}${field('🧯 เงินสำรอง','buffer',p.buffer||'','number','min="0" step="1"')}</div><p><b>ยอดแผนปัจจุบัน ${thb(p.total)}</b></p>`)}
