document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!controlActions130.has(b.dataset.action))return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.action,date=b.dataset.date||focusTripDate130();if(a==='openfocusday'){day=date;go('plan');return}if(a==='bookinghub'){bookingHub130();return}if(a==='routehub'){routeHub130(date);return}if(a==='freshnesshub'){freshnessHub130(date);return}if(a==='budgetplanner'){budgetPlanner130();return}if(a==='altplan'){altPlanModal130(date);return}},true);
