const minText140=n=>{n=Math.max(0,Math.round(n));return n<60?`${n} นาที`:`${Math.floor(n/60)} ชม. ${n%60?`${n%60} นาที`:''}`.trim()};
const tokyoClock140=()=>{const parts=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return {date:`${parts.year}-${parts.month}-${parts.day}`,time:`${parts.hour}:${parts.minute}`,minutes:Number(parts.hour)*60+Number(parts.minute)}};
const eventMeta140=e=>e?.discoverId?discover.entrySummary(e.discoverId):null;
