 for(const a of anchors){const segment=original.slice(cursor,a.i).filter(e=>mins140(e.time)==null),anchorCoord=areaCoord140(a.e);suggested.push(...optimizeSegment140(segment,prevCoord,anchorCoord),a.e);prevCoord=anchorCoord||prevCoord;cursor=a.i+1}
