 // Safety: include anything missed, exactly once.
 for(const e of original)if(!suggested.includes(e))suggested.push(e);
 const changed=suggested.some((e,i)=>e.id!==original[i]?.id),cities=[...new Set(suggested.map(eventMeta140).filter(Boolean).map(x=>x.city))];
